{
  "story": "How does k-means clustering work? Start with five points and two seeded centers. Assign each point to its nearest center, then replace centers with cluster means. Watch Point R switch after the centers move. Repeat until assignments stop changing. Use Previous and Next to compare the states.",
  "aha": {
    "stateId": "stable",
    "observation": "Point R switches after the centers move; repeating assignment and mean updates ends with unchanged assignments."
  },
  "layout": {
    "preset": "approved-card",
    "width": 640
  },
  "parts": [
    {
      "id": "steps",
      "kind": "step-rail",
      "presentation": "Place below the story and instructions, above the experiment. Use the canonical algorithm/collection composition. Highlight the active state; progress belongs here. State indices represent algorithm states, never elapsed time. Reference capture shows Stable.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "clustering-picture",
      "kind": "fixed-picture",
      "presentation": "Show fixed array cells P, Q, R, S, T, with Center A and Center B below. Each region displays its phases entry at the active step's index. Coordinates remain fixed; membership words change. Cell spacing does not encode distance. Use membership text and highlighting, never color alone. Fixed inputs are the displayed coordinates, k=2, and the centers shown in Seed. Assume one-dimensional Euclidean distance. Ties choose A; none occur here. No cluster becomes empty.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "mechanism-callout",
      "kind": "active-callout",
      "presentation": "Anchor to the named active part without covering cells. Reserve wrapping space for every state. Identify the mechanism here; numerical measurements belong in the readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "measurements-and-status",
      "kind": "value-readout",
      "presentation": "Place measurements below the picture in two columns, followed by the bound status line. Positions and distances use arbitrary x-units and a common origin. Distances are absolute coordinate differences; centers are arithmetic means of assigned coordinates. Update arrows compare previous and current center positions; distances always use current centers. All displayed measurements are exact integers for these inputs. Balanced depth has zero parameter controls, excluding navigation and reset.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Step",
      "presentation": "Use Previous and Next, retaining their names when disabled at boundaries. Default is Seed; bounds are the listed states; increment is one state. Every state persists until learner action, including Stable. Provide visible focus and keyboard activation. Left Arrow selects Previous; Right Arrow selects Next."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore Seed and all fixed defaults. Provide the accessible name Reset, visible focus, and keyboard activation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "One-dimensional k-means with two clusters",
        "regions": [
          {
            "id": "point-p",
            "label": "Point P",
            "phases": [
              "x=0 · Unassigned",
              "x=0 · Cluster A",
              "x=0 · Cluster A",
              "x=0 · Cluster A",
              "x=0 · Cluster A",
              "x=0 · Cluster A"
            ]
          },
          {
            "id": "point-q",
            "label": "Point Q",
            "phases": [
              "x=2 · Unassigned",
              "x=2 · Cluster A",
              "x=2 · Cluster A",
              "x=2 · Cluster A",
              "x=2 · Cluster A",
              "x=2 · Cluster A"
            ]
          },
          {
            "id": "point-r",
            "label": "Point R",
            "phases": [
              "x=4 · Unassigned",
              "x=4 · Cluster B",
              "x=4 · Cluster B",
              "x=4 · Cluster A",
              "x=4 · Cluster A",
              "x=4 · Cluster A"
            ]
          },
          {
            "id": "point-s",
            "label": "Point S",
            "phases": [
              "x=10 · Unassigned",
              "x=10 · Cluster B",
              "x=10 · Cluster B",
              "x=10 · Cluster B",
              "x=10 · Cluster B",
              "x=10 · Cluster B"
            ]
          },
          {
            "id": "point-t",
            "label": "Point T",
            "phases": [
              "x=16 · Unassigned",
              "x=16 · Cluster B",
              "x=16 · Cluster B",
              "x=16 · Cluster B",
              "x=16 · Cluster B",
              "x=16 · Cluster B"
            ]
          },
          {
            "id": "center-a",
            "label": "Center A",
            "phases": [
              "Seeded",
              "Held fixed during assignment",
              "Replaced by Cluster A's mean",
              "Held fixed during assignment",
              "Replaced by Cluster A's mean",
              "Cluster A's mean remains unchanged"
            ]
          },
          {
            "id": "center-b",
            "label": "Center B",
            "phases": [
              "Seeded",
              "Held fixed during assignment",
              "Replaced by Cluster B's mean",
              "Held fixed during assignment",
              "Replaced by Cluster B's mean",
              "Cluster B's mean remains unchanged"
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "seed",
            "label": "Seed",
            "short": "Initialize",
            "sentence": "Begin with seeded centers and unassigned points.",
            "why": "These fixed starting centers determine the first assignment; different seeds can produce different outcomes.",
            "active": [
              "center-a",
              "center-b"
            ],
            "calloutRegion": "center-b",
            "readouts": [
              {
                "id": "center-a-position",
                "label": "Center A position",
                "value": "0"
              },
              {
                "id": "center-b-position",
                "label": "Center B position",
                "value": "6"
              },
              {
                "id": "r-distance-a",
                "label": "R distance to A",
                "value": "4"
              },
              {
                "id": "r-distance-b",
                "label": "R distance to B",
                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Ready for nearest-center assignment"
              }
            ]
          },
          {
            "id": "assign-first",
            "label": "Assign",
            "short": "Nearest centers",
            "sentence": "Assign each point to its nearest center; Point R joins Cluster B.",
            "why": "Keep centers fixed during assignment. P and Q choose A; R, S, and T choose B.",
            "active": [
              "point-p",
              "point-q",
              "point-r",
              "point-s",
              "point-t"
            ],
            "calloutRegion": "point-r",
            "readouts": [
              {
                "id": "center-a-position",
                "label": "Center A position",
                "value": "0"
              },
              {
                "id": "center-b-position",
                "label": "Center B position",
                "value": "6"
              },
              {
                "id": "r-distance-a",
                "label": "R distance to A",
                "value": "4"
              },
              {
                "id": "r-distance-b",
                "label": "R distance to B",
                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Assigned; recompute means next"
              }
            ]
          },
          {
            "id": "means-first",
            "label": "Update means",
            "short": "Move centers",
            "sentence": "Replace each center with the mean of its assigned points.",
            "why": "Point R is now closer to A, but its membership remains B until the next assignment step.",
            "active": [
              "center-a",
              "center-b"
            ],
            "calloutRegion": "center-b",
            "readouts": [
              {
                "id": "center-a-position",
                "label": "Center A position",
                "value": "0 → 1"
              },
              {
                "id": "center-b-position",
                "label": "Center B position",
                "value": "6 → 10"
              },
              {
                "id": "r-distance-a",
                "label": "R distance to A",
                "value": "3"
              },
              {
                "id": "r-distance-b",
                "label": "R distance to B",
                "value": "6"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Means updated; reassignment next"
              }
            ]
          },
          {
            "id": "assign-second",
            "label": "Reassign",
            "short": "R switches",
            "sentence": "Point R switches to Cluster A because the updated Center A is nearer.",
            "why": "The other memberships stay unchanged. Moving the centers changed the nearest-center comparison for Point R.",
            "active": [
              "point-r"
            ],
            "calloutRegion": "point-r",
            "readouts": [
              {
                "id": "center-a-position",
                "label": "Center A position",
                "value": "1"
              },
              {
                "id": "center-b-position",
                "label": "Center B position",
                "value": "10"
              },
              {
                "id": "r-distance-a",
                "label": "R distance to A",
                "value": "3"
              },
              {
                "id": "r-distance-b",
                "label": "R distance to B",
                "value": "6"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Membership changed; recompute means"
              }
            ]
          },
          {
            "id": "means-second",
            "label": "Update means",
            "short": "New cluster means",
            "sentence": "Recompute both means using the changed memberships.",
            "why": "P, Q, and R determine Center A; S and T determine Center B. Membership stays fixed during this update.",
            "active": [
              "center-a",
              "center-b"
            ],
            "calloutRegion": "center-a",
            "readouts": [
              {
                "id": "center-a-position",
                "label": "Center A position",
                "value": "1 → 2"
              },
              {
                "id": "center-b-position",
                "label": "Center B position",
                "value": "10 → 13"
              },
              {
                "id": "r-distance-a",
                "label": "R distance to A",
                "value": "2"
              },
              {
                "id": "r-distance-b",
                "label": "R distance to B",
                "value": "9"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Means updated; check assignments again"
              }
            ]
          },
          {
            "id": "stable",
            "label": "Stable",
            "short": "Assignments unchanged",
            "sentence": "Another nearest-center assignment changes nothing, so this run stops.",
            "why": "Every point remains nearest its assigned center, and both centers equal their assigned points' means.",
            "active": [
              "point-r",
              "center-a",
              "center-b"
            ],
            "calloutRegion": "point-r",
            "readouts": [
              {
                "id": "center-a-position",
                "label": "Center A position",
                "value": "2"
              },
              {
                "id": "center-b-position",
                "label": "Center B position",
                "value": "13"
              },
              {
                "id": "r-distance-a",
                "label": "R distance to A",
                "value": "2"
              },
              {
                "id": "r-distance-b",
                "label": "R distance to B",
                "value": "9"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "No assignments changed; stop"
              }
            ]
          }
        ]
      }
    ]
  }
}
